import hashlib,json,subprocess
from pathlib import Path
def validate():
 f=json.loads(Path('artifact:native-fp8-ema-r1-freeze.json').read_text());root=Path.cwd();assert str(root)==f['root'];assert subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()==f['head']
 assert all(hashlib.sha256((root/p).read_bytes()).hexdigest()==h for p,h in f['files'].items())
 return {'head':f['head'],'patch_sha256':f['patch_sha256'],'guarded_files':len(f['files'])}

